{
  "quantity": {
    "description": "Change in own-team expected single-game scoring margin from adopting the strategy",
    "units": "points",
    "support": "unbounded real; positive favors own team"
  },
  "strategies": [
    {
      "bucket": "analytics",
      "type": "game_management",
      "title": "Aggressive fourth-down conversion policy",
      "recommendation": "Go for fourth down materially more often when win-probability and expected-points models favor it, especially between roughly the opponent's 45-yard line and the high-red-zone range. Build a short-yardage menu so the decision is executable rather than merely theoretical.",
      "rationale": "Public win-probability and expected-points research generally finds that NFL teams punt or attempt field goals too often in favorable fourth-down situations. Converting an extra possession while already in useful field position raises expected points and therefore scoring margin.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.37,
          "interval_95_low": -0.08,
          "interval_95_high": 0.82,
          "shape": "symmetric",
          "tails": "moderate"
        },
        "distribution_family": {
          "name": "normal",
          "justification": "The evidence base is broad enough to center the prior above zero, but game-specific conversion ability and opponent response create meaningful uncertainty in both directions. A normal distribution represents a roughly symmetric, moderately bounded belief."
        },
        "parameters": {
          "mu": 0.37,
          "sigma": 0.2296,
          "conversion_note": "normal(mu, sigma): mu = 0.37. sigma = (0.82 - (-0.08)) / (2 x 1.96) = 0.90 / 3.92 = 0.2296."
        },
        "consistency_check": "The most plausible value, 0.37, is inside [-0.08, 0.82]. A normal distribution has support over all real numbers, including negative and positive scoring-margin effects."
      }
    },
    {
      "bucket": "analytics",
      "type": "offensive",
      "title": "Early-down play-action without run prerequisites",
      "recommendation": "Use more early-down play-action from credible run formations, including when the offense has not first established a successful rushing game. Retain enough real runs from those formations to preserve defensive conflict, but do not wait for a rushing narrative before calling play-action.",
      "rationale": "Public EPA research has repeatedly found that play-action can improve passing efficiency even when prior rushing success is limited. Better early-down efficiency creates fewer long-yardage situations, sustains drives, and raises expected scoring.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.24,
          "interval_95_low": -0.27,
          "interval_95_high": 0.75,
          "shape": "symmetric",
          "tails": "heavy"
        },
        "distribution_family": {
          "name": "student_t",
          "justification": "The public evidence favors play-action on average, but its effect can vary sharply with quarterback mechanics, protection, personnel credibility, and opponent tendencies. A Student-t prior allows a non-trivial chance that the true effect is much better or worse than expected."
        },
        "parameters": {
          "nu": 7,
          "mu": 0.24,
          "sigma": 0.2161,
          "conversion_note": "student_t(nu, mu, sigma): nu = 7 and t_0.975,7 approximately equals 2.36. mu = 0.24. sigma = (0.75 - (-0.27)) / (2 x 2.36) = 1.02 / 4.72 = 0.2161. Sigma is the t scale parameter, not its standard deviation."
        },
        "consistency_check": "The most plausible value, 0.24, is inside [-0.27, 0.75]. A Student-t distribution has support over all real numbers, including negative and positive effects. The interval is approximate because the cited t critical value is rounded."
      }
    },
    {
      "bucket": "analytics",
      "type": "defensive",
      "title": "Four-rush simulated-pressure default",
      "recommendation": "On standard passing downs, reduce predictable true blitzes and rely more often on four-man simulated pressures paired with sound match or split-safety coverage. Keep high-blitz calls for opponents with clearly identified protection or quarterback-processing weaknesses.",
      "rationale": "Public pressure, blitz-rate, and coverage-EPA work generally indicates that pressure quality matters more than simply sending extra rushers, while blitzing can expose explosive-play vulnerability. Simulated pressure can create protection uncertainty without surrendering as much coverage integrity, reducing opponent expected points.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.16,
          "interval_95_low": -0.39,
          "interval_95_high": 0.71,
          "shape": "symmetric",
          "tails": "moderate"
        },
        "distribution_family": {
          "name": "normal",
          "justification": "Public analytics supports the general direction, but the causal effect depends heavily on the pass rush, coverage personnel, and opposing quarterback. The uncertainty is substantial but not assumed to have especially heavy tails."
        },
        "parameters": {
          "mu": 0.16,
          "sigma": 0.2806,
          "conversion_note": "normal(mu, sigma): mu = 0.16. sigma = (0.71 - (-0.39)) / (2 x 1.96) = 1.10 / 3.92 = 0.2806."
        },
        "consistency_check": "The most plausible value, 0.16, is inside [-0.39, 0.71]. A normal distribution has support over all real numbers, including negative and positive scoring-margin effects."
      }
    },
    {
      "bucket": "intuition",
      "type": "game_management",
      "title": "Anti-chaos timeout override",
      "recommendation": "Use a timeout before the snap when coaches can clearly identify an imminent operational failure, such as an uncovered eligible receiver, an unblocked free rusher, or a catastrophic personnel mismatch. Do not save timeouts mechanically when the immediate expected cost of the play appears much larger than the future clock value of the timeout.",
      "rationale": "A prevented busted play can avert a large swing in field position or points, which can outweigh the value of preserving a timeout. This is intuition rather than established analytics because public play-by-play data cannot reliably identify the pre-snap communication failures that coaches can see in real time.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.05,
          "interval_95_low": -0.63,
          "interval_95_high": 0.73,
          "shape": "symmetric",
          "tails": "heavy"
        },
        "distribution_family": {
          "name": "student_t",
          "justification": "The average benefit is likely close to zero because the trigger should be rare, but an incorrect timeout can cost an end-of-half possession while a correct one can prevent a major breakdown. The heavy-tailed Student-t reflects that operational context is largely unmeasured publicly."
        },
        "parameters": {
          "nu": 4,
          "mu": 0.05,
          "sigma": 0.2446,
          "conversion_note": "student_t(nu, mu, sigma): nu = 4 and t_0.975,4 approximately equals 2.78. mu = 0.05. sigma = (0.73 - (-0.63)) / (2 x 2.78) = 1.36 / 5.56 = 0.2446. Sigma is the t scale parameter, not its standard deviation."
        },
        "consistency_check": "The most plausible value, 0.05, is inside [-0.63, 0.73]. A Student-t distribution has support over all real numbers, including negative and positive effects. The interval is approximate because the cited t critical value is rounded."
      }
    },
    {
      "bucket": "intuition",
      "type": "offensive",
      "title": "Immediate complementary-concept sequencing",
      "recommendation": "After a core offensive concept succeeds and the defense shows a recognizable adjustment, call its complementary constraint within the next two to four snaps while personnel and defensive memory are still similar. For example, answer an aggressive downhill reaction to an outside-zone look with a boot, leak, or glance constraint built from the same picture.",
      "rationale": "The objective is to turn a defense's understandable adjustment into a favorable matchup before it can reset, creating occasional efficient gains and explosives. This is intuition rather than established analytics because public data rarely identifies deliberately paired play sequencing, defensive recognition, or the intended constraint relationship between calls.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.09,
          "interval_95_low": -0.46,
          "interval_95_high": 0.64,
          "shape": "symmetric",
          "tails": "moderate"
        },
        "distribution_family": {
          "name": "normal",
          "justification": "I believe sequencing can create small recurring advantages, but the public causal evidence is weak and defenses may not react as expected. The prior is therefore centered only modestly above zero with substantial symmetric uncertainty."
        },
        "parameters": {
          "mu": 0.09,
          "sigma": 0.2806,
          "conversion_note": "normal(mu, sigma): mu = 0.09. sigma = (0.64 - (-0.46)) / (2 x 1.96) = 1.10 / 3.92 = 0.2806."
        },
        "consistency_check": "The most plausible value, 0.09, is inside [-0.46, 0.64]. A normal distribution has support over all real numbers, including negative and positive scoring-margin effects."
      }
    },
    {
      "bucket": "intuition",
      "type": "defensive",
      "title": "One-voice road-noise coverage protocol",
      "recommendation": "On noisy road-game money downs, simplify the coverage-check menu and assign one designated secondary communicator to make the final field-side adjustment. Use a small set of one-word contingency calls rather than asking multiple defenders to negotiate checks amid crowd noise and tempo.",
      "rationale": "A simpler communication structure should reduce the rare but damaging coverage busts that often become explosive passes or touchdowns. This is intuition rather than established analytics because public datasets do not observe who made the check, whether it was heard, or whether a coverage failure was caused by communication rather than execution.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.11,
          "interval_95_low": -0.62,
          "interval_95_high": 0.84,
          "shape": "symmetric",
          "tails": "heavy"
        },
        "distribution_family": {
          "name": "student_t",
          "justification": "The intervention may have little effect for a veteran defense already communicating well, but it could prevent a few extremely costly breakdowns for a less stable unit. A heavy-tailed prior reflects this large dependence on unobserved communication quality."
        },
        "parameters": {
          "nu": 4,
          "mu": 0.11,
          "sigma": 0.2626,
          "conversion_note": "student_t(nu, mu, sigma): nu = 4 and t_0.975,4 approximately equals 2.78. mu = 0.11. sigma = (0.84 - (-0.62)) / (2 x 2.78) = 1.46 / 5.56 = 0.2626. Sigma is the t scale parameter, not its standard deviation."
        },
        "consistency_check": "The most plausible value, 0.11, is inside [-0.62, 0.84]. A Student-t distribution has support over all real numbers, including negative and positive effects. The interval is approximate because the cited t critical value is rounded."
      }
    }
  ]
}
